            const recipient = scanned.replace(/^(bitcoin|solana|ethereum):/i, "").split(/[?@]/)[0];
            await validateRecipient(network, recipient);
            byId("walletSendRecipient").value = recipient;
            qrScannerStream.getTracks().forEach((track) => track.stop());
